init.action:
area.spawner.spawnAll('alien.fighter'); o = area.getObject('fighter'); o.inventory.addItems(getItem("titanium"), 4); o.inventory.addItems(getItem("fighter.gun"), 1);
var a = o.getInterior(player, o.info); for(o in a.getObjectsById('power_core.slot')) o.health = 1;
getStructure("colosseum_exit2").build(null, a, 4*Tile.SIZE, 4*Tile.SIZE);
var o; while((o = a.getObject('ship.bed')) != null) a.removeObject(o);

procedure.action:
setGlobal("originalPlayer", player); setGlobal("originalArea", player.area); setGlobal("points", 500);
		var map = new StringMap(); map.set("alien.bomber", 1); setGlobal("killCounts", map);
		changePlayer("player.colosseum", false); setGlobal("achievement", "bombardment"); player.inventory.addItems(getItem("hamburger"), 4);
		player.inventory.addItems(getItem("laser_gun"), 1); player.inventory.addItems(getItem("missile"), 20);
		player.inventory.addItems(getItem("battery"), 10); player.stats.get("speed").permaBuff(2);
